(4437, 'notification_template_messages.created', 'admin::messages.resource_created', 'Modules\\Notification\\Models\\NotificationTemplateMessage', 'created', 109, NULL, NULL, '{\"old\":[],\"attributes\":{\"template_key\":\"new_device_login_detected\",\"channel_key\":\"email\",\"recipient_role_key\":\"default\",\"title\":{\"en\":\"New Device Login Detected\",\"ar\":\"\\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u062f\\u062e\\u0648\\u0644 \\u0645\\u0646 \\u062c\\u0647\\u0627\\u0632 \\u062c\\u062f\\u064a\\u062f\",\"fr_FR\":\"New Device Login Detected\"},\"subject\":{\"en\":\"New sign-in detected on your account\",\"ar\":\"\\u062a\\u0645 \\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u062f\\u062e\\u0648\\u0644 \\u0645\\u0646 \\u062c\\u0647\\u0627\\u0632 \\u062c\\u062f\\u064a\\u062f\",\"fr_FR\":\"New sign-in detected on your account\"},\"content\":{\"en\":\"<p>Hello {{ user_name }},<\\/p><p>A new sign-in to your {{ app_name }} account was detected from {{ device_name }} at {{ login_time }}.<\\/p><p><strong>Location:<\\/strong> {{ location }}<br><strong>IP address:<\\/strong> {{ ip_address }}<\\/p><p>If this was not you, change your password immediately and review active sessions.<\\/p><p>Thank you,<br>{{ app_name }} Team<\\/p>\",\"ar\":\"<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{ user_name }}\\u060c<\\/p><p>\\u062a\\u0645 \\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u062f\\u062e\\u0648\\u0644 \\u062c\\u062f\\u064a\\u062f \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0641\\u064a {{ app_name }} \\u0645\\u0646 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 {{ device_name }} \\u0641\\u064a {{ login_time }}.<\\/p><p><strong>\\u0627\\u0644\\u0645\\u0648\\u0642\\u0639:<\\/strong> {{ location }}<br><strong>\\u0639\\u0646\\u0648\\u0627\\u0646 IP:<\\/strong> {{ ip_address }}<\\/p><p>\\u0625\\u0630\\u0627 \\u0644\\u0645 \\u062a\\u0643\\u0646 \\u0623\\u0646\\u06