(4471, 'notification_template_messages.created', 'admin::messages.resource_created', 'Modules\\Notification\\Models\\NotificationTemplateMessage', 'created', 142, NULL, NULL, '{\"old\":[],\"attributes\":{\"template_key\":\"suspicious_login_detected\",\"channel_key\":\"email\",\"recipient_role_key\":\"default\",\"title\":{\"en\":\"Suspicious Login Detected\",\"ar\":\"\\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u062f\\u062e\\u0648\\u0644 \\u0645\\u0634\\u0628\\u0648\\u0647\",\"fr_FR\":\"Suspicious Login Detected\"},\"subject\":{\"en\":\"Suspicious sign-in attempt detected\",\"ar\":\"\\u062a\\u0645 \\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u0645\\u062d\\u0627\\u0648\\u0644\\u0629 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u062f\\u062e\\u0648\\u0644 \\u0645\\u0634\\u0628\\u0648\\u0647\\u0629\",\"fr_FR\":\"Suspicious sign-in attempt detected\"},\"content\":{\"en\":\"<p>Hello {{ user_name }},<\\/p><p>We detected a suspicious sign-in attempt on your {{ app_name }} account from {{ device_name }} at {{ login_time }}.<\\/p><p><strong>Location:<\\/strong> {{ location }}<br><strong>IP address:<\\/strong> {{ ip_address }}<\\/p><p>If this was not you, change your password immediately, review active sessions, and contact support if needed.<\\/p><p>Thank you,<br>{{ app_name }} Team<\\/p>\",\"ar\":\"<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{ user_name }}\\u060c<\\/p><p>\\u062a\\u0645 \\u0627\\u0643\\u062a\\u0634\\u0627\\u0641 \\u0645\\u062d\\u0627\\u0648\\u0644\\u0629 \\u062a\\u0633\\u062c\\u064a\\u0644 \\u062f\\u062e\\u0648\\u0644 \\u0645\\u0634\\u0628\\u0648\\u0647\\u0629 \\u0625\\u0644\\u0649 \\u062d\\u0633\\u0627\\u0628\\u0643 \\u0641\\u064a {{ app_name }} \\u0645\\u0646 \\u0627\\u0644\\u062c\\u0647\\u0627\\u0632 {{ device_name }} \\u0641\\u064a {{ login_time }}.<\\/p><p><strong>\\u0627\\u0644\\u0645\\u0648\\u0642\\u0639:<\\/strong> {{ location }}<br><strong>\\u0639\\u0646\\u0648\\u0627\\u0646 IP:<\\/strong> {{ ip_address }}<\\/p><p>\\u0625\\u0630\\u0627 \\u0644\\u0645 \\u062a\\u0643\\u0646 \\u0623\\u0646\\u062a\\u060c \\u064a\\u0631\\u062c\\u0649 \\u062a\\u063a\\u064a\\u064a\\u0631 \\u0643\\u0644\\u0645\\u0629 \\u0627\\u0644\\u0645\\u0631\\u0648\\u0631 \\u0641\\u0648\\u0631\\u0627\\u064b \\u0648\\u0645\\u0631\\u0627\\u062c\\u0639\\u0629 \\u062c\\u0644\\u0633\\u0627\\u062a \\u0627\\u0644\\u062f\\u062e\\u0648\\u0644 \\u0627\\u0644\\u0646\\u0634\\u0637\\u0629 \\u0648\\u0627\\u0644\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639 \\u0627\\u0644\\u062f\\u0639\\u0645 \\u0639\\u0646\\u062f \\u0627\\u0644\\u062d\\u0627\\u062c\\u0629.<\\/p><p>\\u0634\\u0643\\u0631\\u0627\\u064b \\u0644\\u0643\\u060c<br>\\u0641\\u0631\\u064a\\u0642 {{ app_name }}<\\/p>\",\"fr_FR\":\"<p>Hello {{ user_name }},<\\/p><p>We detected a suspicious sign-in attempt on your {{ app_name }} account from {{ device_name }} at {{ login_time }}.<\\/p><p><strong>Location:<\\/strong> {{ location }}<br><strong>IP address:<\\/strong> {{ ip_address }}<\\/p><p>If this was not you, change your password immediately, review active sessions, and contact support if needed.<\\/p><p>Thank you,<br>{{ app_name }} Team<\\/p>\"},\"content_type\":\"html\",\"id\":142},\"info\":{\"ip\":\"127.0.0.1\",\"http_method\":\"POST\",\"user_agent\":\"Mozilla\\/5.0 (Windows NT 10.0; Win64; x64; rv:160.0) Gecko\\/20100101 Firefox\\/160.0\"},\"trans_params\":{\"resource\":\"notification::notification_template_messages.notification_template_message\"}}', '446a238e-101f-4b3f-963b-a32bb903b6bb', '2026-11-12 14:37:02', '2026-11-12 14:37:02');
