(5182, 'notification_template_messages.created', 'admin::messages.resource_created', 'Modules\\Notification\\Models\\NotificationTemplateMessage', 'created', 813, NULL, NULL, '{\"old\":[],\"attributes\":{\"template_key\":\"payslip_updated\",\"channel_key\":\"email\",\"recipient_role_key\":\"default\",\"title\":{\"en\":\"Payslip Updated\",\"ar\":\"\\u062a\\u062d\\u062f\\u064a\\u062b \\u0643\\u0634\\u0641 \\u0627\\u0644\\u0631\\u0627\\u062a\\u0628\",\"fr_FR\":\"Payslip Updated\"},\"subject\":{\"en\":\"Payslip updated for {{ payroll_period }}\",\"ar\":\"\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062b \\u0643\\u0634\\u0641 \\u0627\\u0644\\u0631\\u0627\\u062a\\u0628 \\u0644\\u0644\\u0641\\u062a\\u0631\\u0629 {{ payroll_period }}\",\"fr_FR\":\"Payslip updated for {{ payroll_period }}\"},\"content\":{\"en\":\"<p>Hello {{ user_name }},<\\/p><p>The payslip for {{ employee_name }} for {{ payroll_period }} has been updated. Net salary: {{ net_salary }} {{ currency }}.<\\/p><p>Thank you,<br>{{ app_name }} Team<\\/p>\",\"ar\":\"<p>\\u0645\\u0631\\u062d\\u0628\\u0627\\u064b {{ user_name }}\\u060c<\\/p><p>\\u062a\\u0645 \\u062a\\u062d\\u062f\\u064a\\u062b \\u0643\\u0634\\u0641 \\u0631\\u0627\\u062a\\u0628 \\u0627\\u0644\\u0645\\u0648\\u0638\\u0641 {{ employee_name }} \\u0644\\u0644\\u0641\\u062a\\u0631\\u0629 {{ payroll_period }}. \\u0635\\u0627\\u0641\\u064a \\u0627\\u0644\\u0631\\u0627\\u062a\\u0628: {{ net_salary }} {{ currency }}.<\\/p><p>\\u0634\\u0643\\u0631\\u0627\\u064b \\u0644\\u0643\\u060c<br>\\u0641\\u0631\\u064a\\u0642 {{ app_name }}<\\/p>\",\"fr_FR\":\"<p>Hello {{ user_name }},<\\/p><p>The payslip for {{ employee_name }} for {{ payroll_period }} has been updated. Net salary: {{ net_salary }} {{ currency }}.<\\/p><p>Thank you,<br>{{ app_name }} Team<\\/p>\"},\"content_type\":\"html\",\"id\":813},\"info\":{\"ip\":\"127.0.0.1\",\"http_method\":\"POST\",\"user_agent\":\"Mozilla\\/5.0 (Windows NT 10.0; Win64; x64; rv:160.0) Gecko\\/20100101 Firefox\\/160.0\"},\"trans_pa