INSERT INTO `notification_template_messages` (`id`, `template_key`, `channel_key`, `recipient_role_key`, `title`, `subject`, `content`, `content_type`, `created_at`, `updated_at`) VALUES
(1, 'account_created', 'email', 'default', '{\"en\":\"Account Created\",\"ar\":\"تم إنشاء الحساب\",\"fr_FR\":\"Account Created\"}', '{\"en\":\"Welcome to {{ app_name }}\",\"ar\":\"مرحباً بك في {{ app_name }}\",\"fr_FR\":\"Welcome to {{ app_name }}\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>Your {{ app_name }} account has been created successfully for {{ account_email }}. You can now sign in and start using the available features.</p><p>If you did not request this account, please contact support immediately.</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>تم إنشاء حسابك في {{ app_name }} بنجاح باستخدام البريد {{ account_email }}. يمكنك الآن تسجيل الدخول والبدء باستخدام الميزات المتاحة.</p><p>إذا لم تطلب إنشاء هذا الحساب، يرجى التواصل مع الدعم فوراً.</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>Your {{ app_name }} account has been created successfully for {{ account_email }}. You can now sign in and start using the available features.</p><p>If you did not request this account, please contact support immediately.</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
(2, 'account_created', 'email', 'customer', '{\"en\":\"Account Created - Customer update\",\"ar\":\"تم إنشاء الحساب - للعميل\",\"fr_FR\":\"Account Created - Customer update\"}', '{\"en\":\"Account Created - Customer update\",\"ar\":\"تم إنشاء الحساب - للعميل\",\"fr_FR\":\"Account Created - Customer update\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>This update is for your record and next steps.</p><p>Hello {{ user_name }},</p><p>Your {{ app_name }} account has been created successfully for {{ account_email }}. You can now sign in and start using the available features.</p><p>If you did not request this account, please contact support immediately.</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>هذا التحديث خاص بسجلك والخطوات التالية.</p><p>مرحباً {{ user_name }}،</p><p>تم إنشاء حسابك في {{ app_name }} بنجاح باستخدام البريد {{ account_email }}. يمكنك الآن تسجيل الدخول والبدء باستخدام الميزات المتاحة.</p><p>إذا لم تطلب إنشاء هذا الحساب، يرجى التواصل مع الدعم فوراً.</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>This update is for your record and next steps.</p><p>Hello {{ user_name }},</p><p>Your {{ app_name }} account has been created successfully for {{ account_email }}. You can now sign in and start using the available features.</p><p>If you did not request this account, please contact support immediately.</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
(3, 'account_created', 'email', 'staff', '{\"en\":\"Account Created - Employee update\",\"ar\":\"تم إنشاء الحساب - للموظف\",\"fr_FR\":\"Account Created - Employee update\"}', '{\"en\":\"Account Created - Employee update\",\"ar\":\"تم إنشاء الحساب - للموظف\",\"fr_FR\":\"Account Created - Employee update\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>This employee update is for your attention.</p><p>Hello {{ user_name }},</p><p>Your {{ app_name }} account has been created successfully for {{ account_email }}. You can now sign in and start using the available features.</p><p>If you did not request this account, please contact support immediately.</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>هذا التحديث الوظيفي يحتاج إلى انتباهك.</p><p>مرحباً {{ user_name }}،</p><p>تم إنشاء حسابك في {{ app_name }} بنجاح باستخدام البريد {{ account_email }}. يمكنك الآن تسجيل الدخول والبدء باستخدام الميزات المتاحة.</p><p>إذا لم تطلب إنشاء هذا الحساب، يرجى التواصل مع الدعم فوراً.</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>This employee update is for your attention.</p><p>Hello {{ user_name }},</p><p>Your {{ app_name }} account has been created successfully for {{ account_email }}. You can now sign in and start using the available features.</p><p>If you did not request this account, please contact support immediately.</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
(4, 'account_created', 'in_app', 'default', '{\"en\":\"Account Created\",\"ar\":\"تم إنشاء الحساب\",\"fr_FR\":\"Account Created\"}', '{\"en\":null}', '{\"en\":\"Your account for {{ account_email }} has been created successfully.\",\"ar\":\"تم إنشاء حسابك للبريد {{ account_email }} بنجاح.\",\"fr_FR\":\"Your account for {{ account_email }} has been created successfully.\"}', 'text', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
