(140, 'new_device_login_detected', 'push_notification', 'hr_officer', '{\"en\":\"New Device Login Detected - HR review\",\"ar\":\"اكتشاف تسجيل دخول من جهاز جديد - للموارد البشرية\",\"fr_FR\":\"New Device Login Detected - HR review\"}', '{\"en\":null}', '{\"en\":\"HR review update. Check the employee record and follow up if needed. - {{ app_name }} New sign-in detected from {{ device_name }}.\",\"ar\":\"تحديث لمراجعة الموارد البشرية. تحقق من سجل الموظف وتابع عند الحاجة. - {{ app_name }} تم اكتشاف تسجيل دخول جديد من {{ device_name }}.\",\"fr_FR\":\"HR review update. Check the employee record and follow up if needed. - {{ app_name }} New sign-in detected from {{ device_name }}.\"}', 'text', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
(141, 'new_device_login_detected', 'push_notification', 'staff', '{\"en\":\"New Device Login Detected - Employee update\",\"ar\":\"اكتشاف تسجيل دخول من جهاز جديد - للموظف\",\"fr_FR\":\"New Device Login Detected - Employee update\"}', '{\"en\":null}', '{\"en\":\"This employee update is for your attention. - {{ app_name }} New sign-in detected from {{ device_name }}.\",\"ar\":\"هذا التحديث الوظيفي يحتاج إلى انتباهك. - {{ app_name }} تم اكتشاف تسجيل دخول جديد من {{ device_name }}.\",\"fr_FR\":\"This employee update is for your attention. - {{ app_name }} New sign-in detected from {{ device_name }}.\"}', 'text', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
(142, 'suspicious_login_detected', 'email', 'default', '{\"en\":\"Suspicious Login Detected\",\"ar\":\"اكتشاف تسجيل دخول مشبوه\",\"fr_FR\":\"Suspicious Login Detected\"}', '{\"en\":\"Suspicious sign-in attempt detected\",\"ar\":\"تم اكتشاف محاولة تسجيل دخول مشبوهة\",\"fr_FR\":\"Suspicious sign-in attempt detected\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>We detected a suspicious sign-in attempt on your {{ app_name }} account from {{ device_name }} at {{ login_time }}.</p><p><strong>Location:</strong> {{ location }}<br><strong>IP address:</strong> {{ ip_address }}</p><p>If this was not you, change your password immediately, review active sessions, and contact support if needed.</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>تم اكتشاف محاولة تسجيل دخول مشبوهة إلى حسابك في {{ app_name }} من الجهاز {{ device_name }} في {{ login_time }}.</p><p><strong>الموقع:</strong> {{ location }}<br><strong>عنوان IP:</strong> {{ ip_address }}</p><p>إذا لم تكن أنت، يرجى تغيير كلمة المرور فوراً ومراجعة جلسات الدخول النشطة والتواصل مع الدعم عند الحاجة.</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>We detected a suspicious sign-in attempt on your {{ app_name }} account from {{ device_name }} at {{ login_time }}.</p><p><strong>Location:</strong> {{ location }}<br><strong>IP address:</strong> {{ ip_address }}</p><p>If this was not you, change your password immediately, review active sessions, and contact support if needed.</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
(143, 'suspicious_login_detected', 'email', 'admin', '{\"en\":\"Suspicious Login Detected - Management review\",\"ar\":\"اكتشاف تسجيل دخول مشبوه - للمراجعة الإدارية\",\"fr_FR\":\"Suspicious Login Detected - Management review\"}', '{\"en\":\"Suspicious Login Detected - Management review\",\"ar\":\"اكتشاف تسجيل دخول مشبوه - للمراجعة الإدارية\",\"fr_FR\":\"Suspicious Login Detected - Management review\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>Management visibility update. Review the related record if action is needed.</p><p>Hello {{ user_name }},</p><p>We detected a suspicious sign-in attempt on your {{ app_name }} account from {{ device_name }} at {{ login_time }}.</p><p><strong>Location:</strong> {{ location }}<br><strong>IP address:</strong> {{ ip_address }}</p><p>If this was not you, change your password immediately, review active sessions, and contact support if needed.</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>تحديث للمتابعة الإدارية. راجع السجل المرتبط إذا كان هناك إجراء مطلوب.</p><p>مرحباً {{ user_name }}،</p><p>تم اكتشاف محاولة تسجيل دخول مشبوهة إلى حسابك في {{ app_name }} من الجهاز {{ device_name }} في {{ login_time }}.</p><p><strong>الموقع:</strong> {{ location }}<br><strong>عنوان IP:</strong> {{ ip_address }}</p><p>إذا لم تكن أنت، يرجى تغيير كلمة المرور فوراً ومراجعة جلسات الدخول النشطة والتواصل مع الدعم عند الحاجة.</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>Management visibility update. Review the related record if action is needed.</p><p>Hello {{ user_name }},</p><p>We detected a suspicious sign-in attempt on your {{ app_name }} account from {{ device_name }} at {{ login_time }}.</p><p><strong>Location:</strong> {{ location }}<br><strong>IP address:</strong> {{ ip_address }}</p><p>If this was not you, change your password immediately, review active sessions, and contact support if needed.</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:02', '2026-11-12 14:37:02'),
