(204, 'order_created', 'whatsapp', 'default', '{\"en\":\"Order Created\",\"ar\":\"إنشاء الطلب\",\"fr_FR\":\"Order Created\"}', '{\"en\":null}', '{\"en\":\"Hello {{ user_name }}, order {{ order_number }} was created at {{ branch_name }}. Status: {{ order_status }}. Total: {{ order_total }} {{ currency }}.\",\"ar\":\"مرحباً {{ user_name }}، تم إنشاء الطلب {{ order_number }} في {{ branch_name }}. الحالة: {{ order_status }}. الإجمالي: {{ order_total }} {{ currency }}.\",\"fr_FR\":\"Hello {{ user_name }}, order {{ order_number }} was created at {{ branch_name }}. Status: {{ order_status }}. Total: {{ order_total }} {{ currency }}.\"}', 'text', '2026-11-12 14:37:03', '2026-11-12 14:37:03'),
