(630, 'attendance_manual_adjusted', 'email', 'default', '{\"en\":\"Attendance Manually Adjusted\",\"ar\":\"تعديل الحضور يدوياً\",\"fr_FR\":\"Attendance Manually Adjusted\"}', '{\"en\":\"Attendance manually adjusted for {{ employee_name }}\",\"ar\":\"تم تعديل حضور الموظف {{ employee_name }} يدوياً\",\"fr_FR\":\"Attendance manually adjusted for {{ employee_name }}\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>The attendance record for {{ employee_name }} on {{ attendance_date }} was manually adjusted by {{ adjusted_by }}.</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>تم تعديل سجل حضور الموظف {{ employee_name }} بتاريخ {{ attendance_date }} يدوياً بواسطة {{ adjusted_by }}.</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>The attendance record for {{ employee_name }} on {{ attendance_date }} was manually adjusted by {{ adjusted_by }}.</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:05', '2026-11-12 14:37:05'),
