(889, 'pos_session_closed', 'email', 'default', '{\"en\":\"POS Session Closed\",\"ar\":\"إغلاق جلسة نقطة البيع\",\"fr_FR\":\"POS Session Closed\"}', '{\"en\":\"POS session {{ session_number }} closed\",\"ar\":\"تم إغلاق جلسة نقطة البيع {{ session_number }}\",\"fr_FR\":\"POS session {{ session_number }} closed\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>POS session {{ session_number }} at {{ branch_name }} was closed by {{ cashier_name }} at {{ closed_at }}.</p><p><strong>Closing amount:</strong> {{ closing_amount }} {{ currency }}</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>تم إغلاق جلسة نقطة البيع {{ session_number }} في {{ branch_name }} بواسطة {{ cashier_name }} في {{ closed_at }}.</p><p><strong>مبلغ الإغلاق:</strong> {{ closing_amount }} {{ currency }}</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>POS session {{ session_number }} at {{ branch_name }} was closed by {{ cashier_name }} at {{ closed_at }}.</p><p><strong>Closing amount:</strong> {{ closing_amount }} {{ currency }}</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:06', '2026-11-12 14:37:06'),
