(939, 'gift_card_issued', 'email', 'default', '{\"en\":\"Gift Card Issued\",\"ar\":\"إصدار بطاقة هدية\",\"fr_FR\":\"Gift Card Issued\"}', '{\"en\":\"Gift card {{ gift_card_code }} issued\",\"ar\":\"تم إصدار بطاقة الهدايا {{ gift_card_code }}\",\"fr_FR\":\"Gift card {{ gift_card_code }} issued\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>Gift card {{ gift_card_code }} has been issued for {{ customer_name }}.</p><p><strong>Initial amount:</strong> {{ amount }} {{ currency }}<br><strong>Current balance:</strong> {{ balance }} {{ currency }}<br><strong>Expiry date:</strong> {{ expiry_date }}</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>تم إصدار بطاقة الهدايا {{ gift_card_code }} للعميل {{ customer_name }}.</p><p><strong>المبلغ الأولي:</strong> {{ amount }} {{ currency }}<br><strong>الرصيد الحالي:</strong> {{ balance }} {{ currency }}<br><strong>تاريخ الانتهاء:</strong> {{ expiry_date }}</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>Gift card {{ gift_card_code }} has been issued for {{ customer_name }}.</p><p><strong>Initial amount:</strong> {{ amount }} {{ currency }}<br><strong>Current balance:</strong> {{ balance }} {{ currency }}<br><strong>Expiry date:</strong> {{ expiry_date }}</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:06', '2026-11-12 14:37:06'),
(940, 'gift_card_issued', 'email', 'customer', '{\"en\":\"Gift Card Issued - Customer update\",\"ar\":\"إصدار بطاقة هدية - للعميل\",\"fr_FR\":\"Gift Card Issued - Customer update\"}', '{\"en\":\"Gift Card Issued - Customer update\",\"ar\":\"إصدار بطاقة هدية - للعميل\",\"fr_FR\":\"Gift Card Issued - Customer update\"}', '{\"en\":\"<p>Hello {{ user_name }},</p><p>This update is for your record and next steps.</p><p>Hello {{ user_name }},</p><p>Gift card {{ gift_card_code }} has been issued for {{ customer_name }}.</p><p><strong>Initial amount:</strong> {{ amount }} {{ currency }}<br><strong>Current balance:</strong> {{ balance }} {{ currency }}<br><strong>Expiry date:</strong> {{ expiry_date }}</p><p>Thank you,<br>{{ app_name }} Team</p>\",\"ar\":\"<p>مرحباً {{ user_name }}،</p><p>هذا التحديث خاص بسجلك والخطوات التالية.</p><p>مرحباً {{ user_name }}،</p><p>تم إصدار بطاقة الهدايا {{ gift_card_code }} للعميل {{ customer_name }}.</p><p><strong>المبلغ الأولي:</strong> {{ amount }} {{ currency }}<br><strong>الرصيد الحالي:</strong> {{ balance }} {{ currency }}<br><strong>تاريخ الانتهاء:</strong> {{ expiry_date }}</p><p>شكراً لك،<br>فريق {{ app_name }}</p>\",\"fr_FR\":\"<p>Hello {{ user_name }},</p><p>This update is for your record and next steps.</p><p>Hello {{ user_name }},</p><p>Gift card {{ gift_card_code }} has been issued for {{ customer_name }}.</p><p><strong>Initial amount:</strong> {{ amount }} {{ currency }}<br><strong>Current balance:</strong> {{ balance }} {{ currency }}<br><strong>Expiry date:</strong> {{ expiry_date }}</p><p>Thank you,<br>{{ app_name }} Team</p>\"}', 'html', '2026-11-12 14:37:06', '2026-11-12 14:37:06');
